	if (!Number.isSafeInteger(value) || value < MIN_DURATION_MS || value > MAX_DURATION_MS) throw invalid('OUT_OF_RANGE', `${path} must be an integer between ${MIN_DURATION_MS} and ${MAX_DURATION_MS}`);
